package org.apache.commons.codec.binary;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.Charsets;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class StringUtils_newStringIso8859_1_TriageGen0Test {

    @Test
    public void testNewStringIso8859_1_NormalString() {
        byte[] input = "Hello World".getBytes(StandardCharsets.ISO_8859_1);
        String expected = "Hello World";
        String actual = StringUtils.newStringIso8859_1(input);
        assertEquals(expected, actual);
    }

    @Test
    public void testNewStringIso8859_1_SpecialCharacters() {
        // ISO-8859-1 specific characters: 
        // 0xA9 is ©, 0xAE is ®
        byte[] input = new byte[]{(byte) 0xA9, (byte) 0xAE};
        String expected = "©®";
        String actual = StringUtils.newStringIso8859_1(input);
        assertEquals(expected, actual);
    }

    @Test
    public void testNewStringIso8859_1_EmptyArray() {
        byte[] input = new byte[0];
        String expected = "";
        String actual = StringUtils.newStringIso8859_1(input);
        assertEquals(expected, actual);
    }

    @Test
    public void testNewStringIso8859_1_NullInput() {
        // The behavior of new String(null, charset) in Java is to throw a NullPointerException.
        // Since the method does not have a null check, we expect NPE.
        try {
            StringUtils.newStringIso8859_1(null);
        } catch (NullPointerException e) {
            // Success
        }
    }

    @Test
    public void testNewStringIso8859_1_SingleByte() {
        byte[] input = new byte[]{0x41}; // 'A'
        String expected = "A";
        String actual = StringUtils.newStringIso8859_1(input);
        assertEquals(expected, actual);
    }

    @Test
    public void testNewStringIso8859_1_AllBytes() {
        byte[] input = new byte[256];
        for (int i = 0; i < 256; i++) {
            input[i] = (byte) i;
        }
        String actual = StringUtils.newStringIso8859_1(input);
        assertEquals(256, actual.length());
        for (int i = 0; i < 256; i++) {
            assertEquals((char) i, actual.charAt(i));
        }
    }
}
